import "./accordion.js";
import { ntgdsGlobal } from "../../__ntgds__";

import { expect, userEvent, within } from "storybook/test";
import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import comp from "./main.js";

const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Accordion",
  loaders: [
    async () => {
      await ntgdsGlobal.run("accordion");
      return {};
    },
  ],
};

const basicArgs = {
  items: [
    {
      title: "What is the NTG Design System?",
      content:
        "<p>The NTG Design System is a comprehensive collection of reusable components, design tokens, and guidelines that help teams build consistent and accessible user interfaces.</p>",
      publishItem: "Yes",
    },
    {
      title: "How do I get started?",
      content:
        "<p>To get started, install the design system package using npm or yarn, then import the components you need into your application.</p>",
      publishItem: "Yes",
    },
    {
      title: "Is it accessible?",
      content:
        "<p>Yes! All components are built with accessibility in mind, following WCAG 2.1 AA guidelines. This includes proper ARIA attributes, keyboard navigation, and focus management.</p>",
      publishItem: "Yes",
    },
  ],
};

const basicHtml = await squiz.markup(basicArgs);

export const Basic = {
  render: (args) => squiz(args),
  args: basicArgs,
  argTypes: {
    items: {
      control: "object",
      description: "Accordion items: { title, content, publishItem }.",
    },
    showToggleAll: {
      control: "boolean",
      description: 'Shows "Open all" / "Close all" button when true.',
    },
  },
  parameters: {
    docs: { source: { code: basicHtml, language: "html", type: "code" } },
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const trigger = await canvas.findByText("What is the NTG Design System?");
    const button = trigger.closest("button");

    await expect(button).toHaveAttribute("aria-expanded", "false");

    await userEvent.click(trigger);
    await expect(button).toHaveAttribute("aria-expanded", "true");

    await userEvent.click(trigger);
    await expect(button).toHaveAttribute("aria-expanded", "false");
  },
};

